mapper.insert:
INSERT INTO session_to_goods (SESSION_ID, GOODS_ID)
SELECT #{sessionHistory}, #{goodsId}
FROM DUAL
WHERE NOT EXISTS (
SELECT 1
FROM (
SELECT SESSION_ID
FROM session_to_goods
WHERE GOODS_ID = #{goodsId}
ORDER BY create_time DESC
LIMIT 1
) t
WHERE t.SESSION_ID = #{sessionHistory}
)

mapper.select:
SELECT IF(from_uid = #{id}, to_uid, from_uid) AS uid
FROM session_state
WHERE from_uid = #{id}
OR to_uid = #{id}
